    {
      "rank": 1,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase expose how quantum phases carry physical information, with consequences across quantum mechanics, condensed matter, and optics. This is foundational physics with lasting reach.",
        "attribution": "Aharonov's contribution is central to the AB effect; Berry identified the general geometric phase. They are related but distinct results, so a shared citation should state that distinction clearly.",
        "maturity": "Both ideas have extensive experimental confirmation and decades of influence.",
        "uncertainties": [
          "The candidate combines discoveries from different periods and contexts; the prize citation would need a sharply defined scope."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Akira Ohtomo",
        "Harold Y. Hwang"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of a conducting two-dimensional electron system at an oxide interface opened a major experimental field in correlated and emergent electronic phases. It is a particularly compelling materials-physics discovery.",
        "attribution": "Ohtomo and Hwang are closely tied to the original LaAlO3/SrTiO3 interface result. The wider development involved many groups, and later emergent phases should not be folded into the original discovery without separate justification.",
        "maturity": "The interface phenomenon and its influence on oxide research have been studied for many years, although some details of the electronic state remain actively debated.",
        "uncertainties": [
          "The exact nature and conditions of interfacial conduction remain contested.",
          "The proposed discovery spans an initial observation and later phases whose contributors differ."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Realizing strongly interacting Fermi gases and probing the BEC-BCS crossover created a remarkably controllable setting for studying fermionic superfluidity and universal many-body physics.",
        "attribution": "The work emerged from several leading experimental groups. These three represent important contributions, but the crossover and its experimental milestones do not reduce neatly to a single experiment or team.",
        "maturity": "The results have been replicated, extended, and used extensively across ultracold-atom physics.",
        "uncertainties": [
          "The boundaries of the credited achievement and the relative contributions of other early groups need careful historical review."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization in ballistic quantum point contacts provided a clear experimental demonstration of quantized transport and helped establish mesoscopic physics.",
        "attribution": "The discovery was made in parallel by independent groups, and the listed names represent important experimental work. The role of earlier theoretical foundations and the exact experimental priority should be reflected in any citation.",
        "maturity": "The effect is robust, repeatedly measured, and a standard result in quantum transport.",
        "uncertainties": [
          "Priority and individual contributions across the parallel 1988 experiments require precise historical attribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement and enabled stringent tests of fundamental physics through unprecedented frequency stability and accuracy.",
        "attribution": "Katori and Ye made distinct, foundational contributions to the clock concept and its realization. Their respective roles are sufficiently identifiable for a focused award.",
        "maturity": "The technology has been independently realized and steadily improved, with clear demonstrations of its scientific value.",
        "uncertainties": [
          "The long-term reach of clock comparisons for fundamental discovery is still developing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of time-reversal-invariant topological insulators established a new phase of matter and a powerful framework for topological quantum materials.",
        "attribution": "Kane and Mele made the central theoretical prediction; Molenkamp's group demonstrated the quantum spin Hall effect in HgTe. The later three-dimensional topological-insulator work broadened the field and involved additional contributors.",
        "maturity": "The underlying topological classification and experimental effects are well established, with extensive subsequent confirmation.",
        "uncertainties": [
          "This candidate overlaps substantially with the separate quantum spin Hall and topological-insulator entries, complicating the prize scope and credit."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of cosmic microwave background anisotropies supplied a landmark quantitative picture of the universe and strongly constrained the standard cosmological model.",
        "attribution": "Bennett and Page were central experimental leaders, while Spergel contributed to the scientific interpretation. A mission-scale result necessarily involves a much larger collaboration.",
        "maturity": "The measurements have been cross-checked and built upon by later observations, making their place in cosmology secure.",
        "uncertainties": [
          "The proposed credit must distinguish instrument, mission, analysis, and theoretical interpretation contributions."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of gamma-ray burst afterglows made it possible to locate bursts and establish their cosmological distances, changing the understanding of these powerful transients.",
        "attribution": "Costa and Frontera are associated with the initial afterglow breakthrough, while Kulkarni made a major contribution to rapid optical follow-up and establishing cosmological origin. The sequence involved several teams.",
        "maturity": "The cosmological origin of gamma-ray bursts is now well supported by extensive observations.",
        "uncertainties": [
          "The discovery chain spans separate instruments and follow-up results, so priority and scope of credit need care."
        ]
      }
    }
  ]
